SIN_TRIGGERS = "ALTER TABLE production_opcomponente DISABLE TRIGGER trg_op_componente_bloqueado;"
CON_TRIGGERS = "ALTER TABLE production_opcomponente ENABLE TRIGGER trg_op_componente_bloqueado;"


def a_salidas(apps, schema_editor):
    """Enmienda 1 de 0005a: cada OP pasa su producto a una salida (factor 1) con lo producido,
    el lote y el costo; sus componentes quedan asignados a ella."""
    Orden = apps.get_model("production", "OrdenProduccion")
    Salida = apps.get_model("production", "OpSalida")
    Componente = apps.get_model("production", "OpComponente")
    schema_editor.execute(SIN_TRIGGERS)  # los componentes de una OP finalizada están bloqueados
    for op in Orden.all_tenants.all():
        producida = op.cantidad_producida
        salida = Salida.all_tenants.create(
            empresa_id=op.empresa_id,
            op_id=op.id,
            producto_id=op.producto_id,
            cantidad=op.cantidad,
            producida=producida,
            lote_codigo=op.lote_codigo,
            costo_total=op.costo_total if producida else 0,
            costo_unitario=op.costo_unitario,
        )
        Componente.all_tenants.filter(op_id=op.id).update(salida=salida)
    schema_editor.execute(CON_TRIGGERS)
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


def a_cabecera(apps, schema_editor):
    """Reversa: la primera salida vuelve a la cabecera de la OP."""
    Orden = apps.get_model("production", "OrdenProduccion")
    Salida = apps.get_model("production", "OpSalida")
    Componente = apps.get_model("production", "OpComponente")
    schema_editor.execute(SIN_TRIGGERS)
    for op in Orden.all_tenants.all():
        x = Salida.all_tenants.filter(op_id=op.id).order_by("id").first()
        Orden.all_tenants.filter(pk=op.id).update(
            producto_id=x.producto_id,
            cantidad=x.cantidad,
            cantidad_producida=x.producida,
            lote_codigo=x.lote_codigo,
            costo_unitario=x.costo_unitario,
        )
    Componente.all_tenants.update(salida=None)
    Salida.all_tenants.all().delete()
    schema_editor.execute(CON_TRIGGERS)
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


